  // Structural elements are either data member pointers or nullptr
  // placeholders used in has<> patterns.
  template <auto M>
  inline constexpr bool
      is_structural_element_v = is_data_member_ptr_v<M>
                                || is_nullptr_placeholder_v<M>;

