#include <type_traits>

namespace ptn::meta {

  // Remove const/volatile qualifiers and references from T.
  template <typename T>
  using remove_cvref_t = std::remove_cv_t<std::remove_reference_t<T>>;

  // Check whether T is a specialization of a given template.
  // Only supports templates of the form: template<typename...> typename Template
  template <template <typename...> typename Template, typename T>
  struct is_spec_of : std::false_type {};

  template <template <typename...> typename Template, typename... Args>
  struct is_spec_of<Template, Template<Args...>> : std::true_type {};

  // Convenience value alias for is_spec_of.
  template <template <typename...> typename Template, typename T>
  inline constexpr bool is_spec_of_v = is_spec_of<Template, T>::value;

  // Detect whether a type is a template instantiation of the form Template<Args...>.
  // This is intentionally lightweight and only supports type templates with type-parameter packs.
  template <typename T>
  struct is_tmpl : std::false_type {};

  template <template <typename...> typename Template, typename... Args>
  struct is_tmpl<Template<Args...>> : std::true_type {};

  // Convenience value alias for is_tmpl.
  template <typename T>
  inline constexpr bool is_tmpl_v = is_tmpl<T>::value;

} // namespace ptn::meta
// ---- end ptn/meta/base/traits.hpp ----

// ---- begin ptn/meta/dsa/type_list.hpp ----

// Compile-time type sequence (type_list) and basic list combinators.

#include <cstddef>

namespace ptn::meta {

  // Simple compile-time container for a pack of types.
  template <typename... Ts>
  struct type_list {
    static constexpr std::size_t size = sizeof...(Ts);
  };

  // Concatenate two type_list sequences.
  template <typename... A, typename... B>
  constexpr auto contact(type_list<A...>, type_list<B...>)
      -> type_list<A..., B...> {
    return {};
  }

  // Append one type to a type_list.
  template <typename T, typename... Ts>
  constexpr auto append(type_list<Ts...>) -> type_list<Ts..., T> {
    return {};
  }

  // Prepend one type to a type_list.
  template <typename T, typename... Ts>
  constexpr auto prepend(type_list<Ts...>) -> type_list<T, Ts...> {
    return {};
  }

  // Retrieve the N-th type from a type_list.
  template <std::size_t N, typename TL>
  struct nth_type;

  template <std::size_t N, typename T, typename... Ts>
  struct nth_type<N, type_list<T, Ts...>> {
    using type = typename nth_type<N - 1, type_list<Ts...>>::type;
  };

  template <typename T, typename... Ts>
  struct nth_type<0, type_list<T, Ts...>> {
    using type = T;
  };

  // Convenience alias for nth_type (index-based lookup).
  template <std::size_t N, typename TL>
  using index_t = typename nth_type<N, TL>::type;

} // namespace ptn::meta
// ---- end ptn/meta/dsa/type_list.hpp ----

// ---- begin ptn/meta/query/template_info.hpp ----

// Introspection helpers for template instantiations.
// Extracts arguments and provides a rebind alias.


namespace ptn::meta {

  // Primary template for non-specialized types.
  // Exposes an empty argument list and no rebind alias.
  template <typename T>
  struct template_info {
    static constexpr bool is_specialization = false;
    using args                              = type_list<>;
    // Intentionally no rebind alias for non-template types.
  };

  template <template <typename...> typename Template, typename... Args>
  struct template_info<Template<Args...>> {
    static constexpr bool is_specialization = true;
    using args                              = type_list<Args...>;

    template <typename... Us>
    using rebind = Template<Us...>;
  };

} // namespace ptn::meta
